CREATE SCHEMA IF NOT EXISTS ecis;
CREATE SCHEMA IF NOT EXISTS security;
CREATE EXTENSION IF NOT EXISTS pgcrypto;

GRANT USAGE ON SCHEMA ecis TO ecis_apl;
GRANT USAGE ON SCHEMA security TO ecis_apl;

INSERT INTO security.role (name,code,enabled,global,created_by) VALUES ('USER','00000',true,false,'SYSTEM'), ('ENCAMPMENT_READ','10000',true,false,'SYSTEM'), ('ENCAMPMENT_DELETE','10001',true,true,'SYSTEM'), ('ENCAMPMENT_CREATE','10002',true,true,'SYSTEM'), ('ENCAMPMENT_EDIT','10003',true,true,'SYSTEM'), ('CHILDREN_READ','20000',true,false,'SYSTEM'), ('CHILDREN_MERGE','20001',true,false,'SYSTEM'), ('CHILDREN_APPLICATION_READ','20002',true,false,'SYSTEM'), ('CHILDREN_ENCAMPMENT_LIST_DOWNLOAD','20003',true,false,'SYSTEM'), ('CHILDREN_ENCAMPMENT_ASSIGN','20004',true,false,'SYSTEM');
INSERT INTO security.role (name,code,enabled,global,created_by) VALUES ('CHILDREN_IMPORT','20005',true,false,'SYSTEM'), ('PARENTS_READ','30000',true,false,'SYSTEM'), ('INJURIES_READ','40000',true,false,'SYSTEM'), ('INJURIES_CREATE','40001',true,false,'SYSTEM'), ('INJURIES_DELETE','40002',true,false,'SYSTEM'), ('INJURIES_REPORT_DOWNLOAD','40003',true,false,'SYSTEM'), ('MEDICAMENTS_OVERVIEW_READ','50000',true,false,'SYSTEM'), ('MEDICAMENTS_HISTORY_READ','50001',true,false,'SYSTEM'), ('MEDICAMENT_DISPOSE','50002',true,false,'SYSTEM'), ('APPLICATION_ARCHIVIST','60000',false,false,'SYSTEM');
INSERT INTO security.role (name,code,enabled,global,created_by) VALUES ('APPLICATION_SHREDDER','60001',false,false,'SYSTEM'), ('APPLICATION_DOWNLOAD','60002',true,false,'SYSTEM'), ('TEST_FORM','70000',false,false,'SYSTEM'), ('CAMP_ARCHIVIST','10004',false,true,'SYSTEM'), ('CHILDREN_CONFIRMATION','20006',true,false,'SYSTEM'), ('MEDICAMENT_ADD','50003',true,false,'SYSTEM'), ('MEDICAMENT_EDIT','50004',true,false,'SYSTEM'), ('MEDICAMENT_DELETE','50005',true,false,'SYSTEM'), ('PARENTS_CONTACTS_READER','30004',true,true,'SYSTEM');

CREATE SCHEMA IF NOT EXISTS log;
CREATE SCHEMA IF NOT EXISTS security;

GRANT USAGE ON SCHEMA log TO ecis_apl;

UPDATE security.role SET name = 'CAMP_READ' WHERE name = 'ENCAMPMENT_READ';
UPDATE security.role SET name = 'CAMP_DELETE' WHERE name = 'ENCAMPMENT_DELETE';
UPDATE security.role SET name = 'CAMP_CREATE' WHERE name = 'ENCAMPMENT_CREATE';
UPDATE security.role SET name = 'CAMP_EDIT' WHERE name = 'ENCAMPMENT_EDIT';

GRANT SELECT, UPDATE, INSERT ON TABLE ecis.child TO ecis_apl;
GRANT SELECT, UPDATE, INSERT ON TABLE ecis.parent TO ecis_apl;

GRANT SELECT, INSERT ON TABLE audit.parent_history TO ecis_apl;
GRANT SELECT, INSERT ON TABLE audit.child_history TO ecis_apl;
